//! Embeds the application icon into Windows executables.
//!
//! Windows takes a program's icon from a resource section compiled into the
//! binary, not from a file shipped alongside it, so there is no way to do this
//! at runtime. `assets/icon.ico` is generated by `tools/make-icon.py` from the
//! same geometry as the macOS and Linux icons.
//!
//! The dependency and this code are both gated to Windows targets, so building
//! on macOS or Linux neither downloads `winresource` nor runs a resource
//! compiler. The gate is the *host* platform, which is what a native Windows
//! build reports; cross-compiling to Windows from another host would need the
//! `cfg` swapped for a `CARGO_CFG_TARGET_OS` check.

#[cfg(windows)]
fn embed_icon() {
    // `compile` applies the resource to every binary in the crate, so `dmux`,
    // `dmux-ddc-helper` and `dmux-gui` all carry the icon.
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(err) = res.compile() {
        // A missing resource compiler should not break the build: the binaries
        // are perfectly usable without an icon.
        println!("cargo:warning=could not embed the Windows icon: {err}");
    }
}

fn main() {
    // Re-run when the icon changes, not just when the source does.
    println!("cargo:rerun-if-changed=assets/icon.ico");

    #[cfg(windows)]
    embed_icon();
}
